#!/usr/bin/env python3
"""Embed repository schemas; --check detects drift without writing files."""
import argparse
import json
from pathlib import Path
import sys


def generate(root):
    output = [
        '// Generated by tool/generate_dart_schemas.py; do not edit by hand.',
        "import 'dart:convert';",
        '',
        'final Map<String, Object?> wireSchemas = {',
    ]
    sources = sorted((root / 'schemas/v0.1').glob('*.schema.json'))
    if not sources:
        raise ValueError('No schemas found')
    for source in sources:
        output.append(f"  '{source.name}': jsonDecode(r'''")
        output.append(json.dumps(json.loads(source.read_text(encoding='utf-8')),
                                 ensure_ascii=False, indent=2))
        output.append("'''),")
    output.append('};')
    return '\n'.join(output) + '\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    root = Path(__file__).resolve().parent.parent
    target = root / 'dart/packages/chatweave_core/lib/src/wire_schemas.dart'
    generated = generate(root)
    if args.check:
        if not target.exists() or target.read_text(encoding='utf-8') != generated:
            print('Dart schemas drifted; run python3 tool/generate_dart_schemas.py',
                  file=sys.stderr)
            return 1
    else:
        target.write_text(generated, encoding='utf-8')
    return 0


if __name__ == '__main__':
    sys.exit(main())
